SELECT age IS DISTINCT FROM id AS a, age IS NOT DISTINCT FROM id AS b, age BETWEEN 1 AND 5 AS c, state IN ('a') AS d, state LIKE '%a%' AS e, state NOT LIKE 'b%' AS f, age <> 3 AS g, age != 3 AS h, state LIKE ANY ('a%', 'b%') AS i, state LIKE ALL ('%a%', '%b%') AS j, NOT (age = 1) AS k, age IS NULL OR age IS NOT NULL AS l, (age = 1) IS TRUE AS m FROM `kumosql.kumosql_messy.raw_users`
